xml.Script:
        Colors[ 0] := '0000A0'; // clBlue
        Colors[ 1] := '008000'; // clGreen
        Colors[ 2] := 'FF0000'; // clRed
        Colors[ 3] := 'FF6000'; // clOrange
        Colors[ 4] := 'FFFF00'; // clYellow
        Colors[ 5] := 'FFFFFF'; // clWhite
        Colors[ 6] := 'AABB20'; // clGolden
        Colors[ 7] := '800080'; // clPurple
        Colors[ 8] := '7FFF00'; // Lime
        Colors[ 9] := '008080'; // Teal
        Colors[10] := '2828FF'; // LightBlue
        Colors[11] := '00FF00'; // LightGreen
        Colors[12] := '800000'; // Brown
        Colors[13] := '8000CF'; // Violett
        Colors[14] := 'FF0080'; // LightViolett
        Colors[15] := '00DCB4'; // Cyan
        Colors[16] := 'FF69B4'; // Pink
        Colors[17] := '808000'; // Olive
        Colors[18] := 'F0E68C'; // Khaki
        Colors[19] := '00BFFF'; // DeepSky

        H := 0.7;
        R := H / sqrt((5 + sqrt(5)) / 2);

        for i := 0 to 9 do begin
            x[i] := R * cos(2 * Pi / 10 * i);
            y[i] := R * sin(2 * Pi / 10 * i);
        end;

        az := R * cos(Pi/10) / H;
        for i := 0 to 9 do begin
            ax[i] := cos(2 * Pi / 10 * (i + 0.5));
            ay[i] := sin(2 * Pi / 10 * (i + 0.5));
        end;

        // Calcs angle from 2 to 3 while rotating over 1
        function Angle(x1, y1, z1, x2, y2, z2, x3, y3, z3);
        begin
          vx := y1 * z2 - y2 * z1;
          vy := z1 * x2 - z2 * x1;
          vz := x1 * y2 - x2 * y1;
          wx := y1 * z3 - y3 * z1;
          wy := z1 * x3 - z3 * x1;
          wz := x1 * y3 - x3 * y1;
          Result := ArcCos((vx*wx + vy*wy + vz*wz) / (vx^2 + vy^2 + vz^2));
        end;

        // Calc all Jumble Angles
        A1 := Angle(ax[0],ay[0],az, ax[1],ay[1],az, ax[9],ay[9],az);
        A2 := Angle(ax[0],ay[0],az, ax[2],ay[2],az, ax[8],ay[8],az);
        A3 := Angle(ax[0],ay[0],az, ax[3],ay[3],az, ax[7],ay[7],az);
        A4 := Angle(ax[0],ay[0],az, ax[4],ay[4],az, ax[6],ay[6],az);
